    for v in row:
        if type(v) is not float:
            raise ValueError("%s entries must be float, got %r" % (name, v))
        if not math.isfinite(v):
            raise ValueError("%s entries must be finite, got %r" % (name, v))
        if v == 0.0 and math.copysign(1.0, v) < 0.0:
            raise ValueError("%s entries must not be -0.0, got %r" % (name, v))
        checked.append(v)
    return checked

